using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class TransformationMorphOperations : RefCounted
{
    public double axis_map(double value,double loA,double hiA,double loB,double hiB){if(value<loA)return value/Math.Max(.00001,loA)*loB;if(value>hiA)return hiB+(value-hiA)/Math.Max(.00001,1-hiA)*(1-hiB);return Mathf.Lerp(loB,hiB,(value-loA)/Math.Max(.00001,hiA-loA));}
    public Vector2 mapped(Vector2 point,Vector2[] first,Vector2[] last){var sum=Vector2.Zero;double total=0;for(int index=0;index<first.Length;index++){double gap=point.DistanceSquaredTo(first[index]);if(gap<.00000001)return last[index];double weight=1/Math.Max(.000000001,gap*gap);sum+=(last[index]-first[index])*(float)weight;total+=weight;}return point+sum/(float)Math.Max(.0000001,total);}
    public Settings identity()=>new() {["valid"]=false,["empty_a"]=false,["empty_b"]=false,["reason"]="Crossfade",["uv_a"]=new[]{Vector2.Zero,Vector2.Right,Vector2.One,Vector2.Down},["uv_b"]=new[]{Vector2.Zero,Vector2.Right,Vector2.One,Vector2.Down},["indices"]=new[]{0,1,2,0,2,3}};
    public Image bounded(Image image,int limit){if(Math.Max(image.GetWidth(),image.GetHeight())<=limit)return image;var result=(Image)image.Duplicate();double scale=(double)limit/Math.Max(image.GetWidth(),image.GetHeight());result.Resize(Math.Max(1,(int)Math.Round(image.GetWidth()*scale,MidpointRounding.AwayFromZero)),Math.Max(1,(int)Math.Round(image.GetHeight()*scale,MidpointRounding.AwayFromZero)),Image.Interpolation.Bilinear);return result;}
    public Settings silhouette(Image image){using var analysis=new MorphAnalysisOperations();return analysis.analyze(image);}
    public Settings prepare(Image? imageA,Image? imageB,Vector2[] pinsA,Vector2[] pinsB,Settings settings,Settings basis)
    {
        var result=identity();if(imageA==null||imageB==null||imageA.IsEmpty()||imageB.IsEmpty()){result["reason"]="Missing source artwork: crossfade fallback.";return result;}int limit=settings.TryGetValue("quality",out var quality)&&quality.AsString()=="High"?192:128;var aImage=bounded(imageA,limit);var bImage=bounded(imageB,limit);
        try {ulong started=Time.GetTicksUsec();using var analysis=new MorphAnalysisOperations();var a=basis.Count>0?basis["analysis_a"].AsGodotDictionary():analysis.analyze(aImage);var b=basis.Count>0?basis["analysis_b"].AsGodotDictionary():analysis.analyze(bImage);bool emptyA=a["empty"].AsBool(),emptyB=b["empty"].AsBool();result["empty_a"]=emptyA;result["empty_b"]=emptyB;result["method"]="Growth";result["topology"]=false;result["bounds_a"]=a.TryGetValue("bounds",out var boundsA)?boundsA:Variant.From(new Rect2(Vector2.Zero,Vector2.One));result["bounds_b"]=b.TryGetValue("bounds",out var boundsB)?boundsB:Variant.From(new Rect2(Vector2.Zero,Vector2.One));if(pinsA.Length!=pinsB.Length){result["reason"]="Invalid correction pair count.";return result;}foreach(var points in new[]{pinsA,pinsB})foreach(var point in points)if(!point.IsFinite()||point.X<0||point.Y<0||point.X>1||point.Y>1){result["reason"]="Invalid correspondence coordinate.";return result;}for(int index=0;index<pinsA.Length;index++)for(int j=0;j<index;j++)if(pinsA[index].DistanceSquaredTo(pinsA[j])<.00000001f||pinsB[index].DistanceSquaredTo(pinsB[j])<.00000001f){result["reason"]="Conflicting correction pairs: crossfade fallback. Remove duplicate markers.";return result;}
            if(!emptyA&&!emptyB){bool validA=a["valid"].AsBool(),validB=b["valid"].AsBool();if(a["regions"].AsInt32()==1&&b["regions"].AsInt32()==1&&a["holes"].AsInt32()==0&&b["holes"].AsInt32()==0&&validA&&validB){using var deformation=new MorphDeformationOperations();var mesh=deformation.prepare(a,b,pinsA,pinsB,settings);if(mesh["valid"].AsBool())result.Merge(mesh,true);else result["reason"]=mesh["reason"];}
                if(!result["valid"].AsBool()){result["topology"]=true;result["method"]="Implicit topology";result["valid"]=true;if(result["reason"].AsString()=="Crossfade")result["reason"]="Signed-distance topology: splitting, merging or holes.";string alignment=settings.TryGetValue("alignment",out var value)?value.AsString():"Bounds";if(alignment=="Bounds"&&validA&&validB){const int grid=20;var uvA=new List<Vector2>();var uvB=new List<Vector2>();var indices=new List<int>();var first=a["bounds"].AsRect2();var last=b["bounds"].AsRect2();for(int y=0;y<=grid;y++)for(int x=0;x<=grid;x++){var uv=new Vector2(x,y)/grid;uvA.Add(uv);uvB.Add(new Vector2((float)axis_map(uv.X,first.Position.X,first.End.X,last.Position.X,last.End.X),(float)axis_map(uv.Y,first.Position.Y,first.End.Y,last.Position.Y,last.End.Y)));}for(int y=0;y<grid;y++)for(int x=0;x<grid;x++){int index=y*(grid+1)+x;indices.AddRange(new[]{index,index+1,index+grid+2,index,index+grid+2,index+grid+1});}result["uv_a"]=uvA.ToArray();result["uv_b"]=uvB.ToArray();result["indices"]=indices.ToArray();}}}else result["reason"]="Empty state: geometric growth / reveal.";
            using var field=new MorphDistanceFieldOperations();result["field_a"]=basis.Count>0?basis["field_a"]:Variant.From(field.build(aImage,a,b["palette"].AsGodotArray()));result["field_b"]=basis.Count>0?basis["field_b"]:Variant.From(field.build(bImage,b,a["palette"].AsGodotArray()));result["basis"]=new Settings {["analysis_a"]=a,["analysis_b"]=b,["field_a"]=result["field_a"],["field_b"]=result["field_b"]};foreach(string name in new[]{"regions","holes"}){result[name+"_a"]=a[name];result[name+"_b"]=b[name];}result["analysis_us"]=(long)(Time.GetTicksUsec()-started);return result;
        } finally {if(aImage!=imageA)aImage.Dispose();if(bImage!=imageB)bImage.Dispose();}
    }
}
